INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-9-31', 'phase-09-lesson-31-pytorch-deep-dive-iii-nn-module-architect', 'module-4', 31, 'Lesson 4.31: PyTorch Deep Dive III: nn.Module Architecture, Parameters & Buffers', 'Prerequisites: Lesson 9.27, Lesson 9.30', 'Prerequisites: Lesson 9.27, Lesson 9.30 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 1550.0, '# Lesson 9.31: PyTorch Deep Dive III: nn.Module Architecture, Parameters & Buffers

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.27, Lesson 9.30
- **Subtopics**:
  - `9.31.1` `nn.Module` internal state: `_parameters`, `_buffers`, `_modules`, `_forward_hooks`, and `_backward_hooks` ordered dictionaries
  - `9.31.2` Parameters vs Buffers: trainable weights (`nn.Parameter`) vs non-trainable state (e.g. running stats, positional embeddings) via `register_buffer`
  - `9.31.3` Weight initialization patterns: applying `init` functions across all submodules using `model.apply(init_weights)`
  - `9.31.4` State dictionaries: `model.state_dict()`, serialization via `torch.save()`, and strict vs non-strict weight loading (`load_state_dict`)
  - `9.31.5` Model modes: `model.train()` vs `model.eval()`, side effects on Dropout, BatchNorm, and customized behavior
  - `9.31.6` Building complex modular architectures: nested `nn.ModuleList`, `nn.ModuleDict`, and residual skip-connection modules
- **Key Failure Modes & Edge Cases**: Storing non-trainable state in standard Python lists or attributes instead of registering as buffers, causing state to be omitted from `state_dict`.
- **Verification & Mastery Check**: Build a modular ResNet-style skip-connection block in PyTorch with custom parameter initialization and persistent registered buffers.
- **Project Application**: PyTorch Engineering: Advanced neural network module design.', '{"solution.py": "# Phase 9 // Lesson 9.31: PyTorch Deep Dive III: nn.Module Architecture, Parameters & Buffers\n\ndef solve():\n    \"\"\"\n    Verification: Build a modular ResNet-style skip-connection block in PyTorch with custom parameter initialization a\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.31", "subtopics_count": 6, "verification_criteria": "Build a modular ResNet-style skip-connection block in PyTorch with custom parameter initialization and persistent registered buffers.", "subtopics": ["9.31.1 `nn.Module` internal state: `_parameters`, `_buffers`, `_modules`, `_forward_hooks`, and `_backward_hooks` ordered dictionaries", "9.31.2 Parameters vs Buffers: trainable weights (`nn.Parameter`) vs non-trainable state (e.g. running stats, positional embeddings) via `register_buffer`", "9.31.3 Weight initialization patterns: applying `init` functions across all submodules using `model.apply(init_weights)`", "9.31.4 State dictionaries: `model.state_dict()`, serialization via `torch.save()`, and strict vs non-strict weight loading (`load_state_dict`)", "9.31.5 Model modes: `model.train()` vs `model.eval()`, side effects on Dropout, BatchNorm, and customized behavior", "9.31.6 Building complex modular architectures: nested `nn.ModuleList`, `nn.ModuleDict`, and residual skip-connection modules"]}'::jsonb, '["Explain how this implementation prevents: Storing non-trainable state in standard Python lists or attributes instead of registering as buffers, causing state to b", "How does PyTorch Deep Dive III: nn.Module Architecture, Parameters & Buffers scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-32', 'phase-09-lesson-32-pytorch-deep-dive-iv-high-performance-dat', 'module-4', 32, 'Lesson 4.32: PyTorch Deep Dive IV: High-Performance DataLoaders & Multiprocessing', 'Prerequisites: Phase 0, Phase 4, Lesson 9.29', 'Prerequisites: Phase 0, Phase 4, Lesson 9.29 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1600.0, '# Lesson 9.32: PyTorch Deep Dive IV: High-Performance DataLoaders & Multiprocessing

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Phase 4, Lesson 9.29
- **Subtopics**:
  - `9.32.1` The data pipeline bottleneck: keeping GPU compute saturating by streaming data asynchronously ahead of execution
  - `9.32.2` `torch.utils.data.Dataset` abstraction: Map-style datasets (`__len__`, `__getitem__`) vs Iterable-style datasets for massive streams
  - `9.32.3` `DataLoader` internals: `batch_size`, `shuffle`, `sampler`, `batch_sampler`, and custom `collate_fn` for dynamic sequence padding
  - `9.32.4` Multiprocessing worker architecture: `num_workers > 0`, process forking vs spawning, and worker initialization functions (`worker_init_fn`)
  - `9.32.5` Avoiding memory leaks in PyTorch DataLoaders: reference cycles, copy-on-write degradation with large Python objects in workers
  - `9.32.6` Prefetching and pinned memory: `pin_memory=True`, `prefetch_factor`, and asynchronous GPU transfers during worker execution
- **Key Failure Modes & Edge Cases**: Worker processes copying large Python lists on fork, exhausting system RAM and triggering Linux OOM killer crashes.
- **Verification & Mastery Check**: Construct a high-performance custom `DataLoader` with dynamic sequence batching, pinned memory, and zero memory leaks under stress.
- **Project Application**: TransformerLab: High-throughput tokenized dataset pipeline.', '{"solution.py": "# Phase 9 // Lesson 9.32: PyTorch Deep Dive IV: High-Performance DataLoaders & Multiprocessing\n\ndef solve():\n    \"\"\"\n    Verification: Construct a high-performance custom `DataLoader` with dynamic sequence batching, pinned memory, and \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.32", "subtopics_count": 6, "verification_criteria": "Construct a high-performance custom `DataLoader` with dynamic sequence batching, pinned memory, and zero memory leaks under stress.", "subtopics": ["9.32.1 The data pipeline bottleneck: keeping GPU compute saturating by streaming data asynchronously ahead of execution", "9.32.2 `torch.utils.data.Dataset` abstraction: Map-style datasets (`__len__`, `__getitem__`) vs Iterable-style datasets for massive streams", "9.32.3 `DataLoader` internals: `batch_size`, `shuffle`, `sampler`, `batch_sampler`, and custom `collate_fn` for dynamic sequence padding", "9.32.4 Multiprocessing worker architecture: `num_workers > 0`, process forking vs spawning, and worker initialization functions (`worker_init_fn`)", "9.32.5 Avoiding memory leaks in PyTorch DataLoaders: reference cycles, copy-on-write degradation with large Python objects in workers", "9.32.6 Prefetching and pinned memory: `pin_memory=True`, `prefetch_factor`, and asynchronous GPU transfers during worker execution"]}'::jsonb, '["Explain how this implementation prevents: Worker processes copying large Python lists on fork, exhausting system RAM and triggering Linux OOM killer crashes.", "How does PyTorch Deep Dive IV: High-Performance DataLoaders & Multiprocessing scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-33', 'phase-09-lesson-33-pytorch-deep-dive-v-mixed-precision-train', 'module-4', 33, 'Lesson 4.33: PyTorch Deep Dive V: Mixed Precision Training (FP16/BF16) & AMP', 'Prerequisites: Phase 0, Lesson 9.29', 'Prerequisites: Phase 0, Lesson 9.29 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 1650.0, '# Lesson 9.33: PyTorch Deep Dive V: Mixed Precision Training (FP16/BF16) & AMP

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 9.29
- **Subtopics**:
  - `9.33.1` Floating-point numerical representations: FP32 (single precision), FP16 (half precision), and BF16 (Bfloat16: 8-bit exponent, 7-bit mantissa)
  - `9.33.2` Why BF16 is superior for deep learning: preserving the dynamic dynamic range of FP32, eliminating underflow/overflow scaling issues
  - `9.33.3` Automatic Mixed Precision (AMP): `torch.autocast`: executing matmuls in FP16/BF16 while accumulating and updating in FP32
  - `9.33.4` Gradient scaling with `torch.cuda.amp.GradScaler`: preventing small gradients from underflowing to zero in FP16 backward passes
  - `9.33.5` Dynamic loss scaling mechanics: scaling loss up before backward, un-scaling gradients before optimizer step, skipping steps with inf/nan
  - `9.33.6` Memory and throughput profiling: measuring $2\times$ memory reduction and $3\times$ throughput speedup on modern tensor core GPUs
- **Key Failure Modes & Edge Cases**: Calling `optimizer.step()` before `scaler.step()` in FP16 training, applying corrupted inf/nan gradients directly to parameters.
- **Verification & Mastery Check**: Instrument a standard PyTorch training loop with `torch.autocast` and `GradScaler`; verify zero gradient underflow and 2.5x speedup.
- **Project Application**: TransformerLab: Mixed precision training pipeline.', '{"solution.py": "# Phase 9 // Lesson 9.33: PyTorch Deep Dive V: Mixed Precision Training (FP16/BF16) & AMP\n\ndef solve():\n    \"\"\"\n    Verification: Instrument a standard PyTorch training loop with `torch.autocast` and `GradScaler`; verify zero grad\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.33", "subtopics_count": 6, "verification_criteria": "Instrument a standard PyTorch training loop with `torch.autocast` and `GradScaler`; verify zero gradient underflow and 2.5x speedup.", "subtopics": ["9.33.1 Floating-point numerical representations: FP32 (single precision), FP16 (half precision), and BF16 (Bfloat16: 8-bit exponent, 7-bit mantissa)", "9.33.2 Why BF16 is superior for deep learning: preserving the dynamic dynamic range of FP32, eliminating underflow/overflow scaling issues", "9.33.3 Automatic Mixed Precision (AMP): `torch.autocast`: executing matmuls in FP16/BF16 while accumulating and updating in FP32", "9.33.4 Gradient scaling with `torch.cuda.amp.GradScaler`: preventing small gradients from underflowing to zero in FP16 backward passes", "9.33.5 Dynamic loss scaling mechanics: scaling loss up before backward, un-scaling gradients before optimizer step, skipping steps with inf/nan", "9.33.6 Memory and throughput profiling: measuring $2\\times$ memory reduction and $3\\times$ throughput speedup on modern tensor core GPUs"]}'::jsonb, '["Explain how this implementation prevents: Calling `optimizer.step()` before `scaler.step()` in FP16 training, applying corrupted inf/nan gradients directly to par", "How does PyTorch Deep Dive V: Mixed Precision Training (FP16/BF16) & AMP scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-34', 'phase-09-lesson-34-pytorch-deep-dive-vi-training-loop-engine', 'module-4', 34, 'Lesson 4.34: PyTorch Deep Dive VI: Training Loop Engineering, Checkpointing & Reproducibility', 'Prerequisites: Lesson 9.28, Lesson 9.33', 'Prerequisites: Lesson 9.28, Lesson 9.33 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 1700.0, '# Lesson 9.34: PyTorch Deep Dive VI: Training Loop Engineering, Checkpointing & Reproducibility

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.28, Lesson 9.33
- **Subtopics**:
  - `9.34.1` Production training loop anatomy: train epoch, validation epoch, metric aggregation, and early stopping criteria
  - `9.34.2` Durable checkpointing: saving model state, optimizer state, scheduler state, epoch count, and scaler state to disk
  - `9.34.3` Resuming interrupted training: exact state restoration, verifying loss trajectory continuity across restarts
  - `9.34.4` Gradient clipping: `torch.nn.utils.clip_grad_norm_`: clipping global $L_2$ norm of concatenated gradients to prevent exploding gradients
  - `9.34.5` Complete determinism and reproducibility: setting seeds across Python `random`, NumPy, PyTorch CPU, PyTorch CUDA, and cuDNN flags
  - `9.34.6` Gradient accumulation: simulating large effective batch sizes ($B_{effective} = B_{physical} \times \text{accum\_steps}$) under constrained VRAM
- **Key Failure Modes & Edge Cases**: Saving only model weights in checkpoints, failing to restore optimizer momentum and learning rate schedule upon resume.
- **Verification & Mastery Check**: Build a production training harness with gradient accumulation, norm clipping, durable checkpointing, and exact resumption verification.
- **Project Application**: TransformerLab: Resilient model training framework.', '{"solution.py": "# Phase 9 // Lesson 9.34: PyTorch Deep Dive VI: Training Loop Engineering, Checkpointing & Reproducibility\n\ndef solve():\n    \"\"\"\n    Verification: Build a production training harness with gradient accumulation, norm clipping, durable checkpointing\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.34", "subtopics_count": 6, "verification_criteria": "Build a production training harness with gradient accumulation, norm clipping, durable checkpointing, and exact resumption verification.", "subtopics": ["9.34.1 Production training loop anatomy: train epoch, validation epoch, metric aggregation, and early stopping criteria", "9.34.2 Durable checkpointing: saving model state, optimizer state, scheduler state, epoch count, and scaler state to disk", "9.34.3 Resuming interrupted training: exact state restoration, verifying loss trajectory continuity across restarts", "9.34.4 Gradient clipping: `torch.nn.utils.clip_grad_norm_`: clipping global $L_2$ norm of concatenated gradients to prevent exploding gradients", "9.34.5 Complete determinism and reproducibility: setting seeds across Python `random`, NumPy, PyTorch CPU, PyTorch CUDA, and cuDNN flags", "9.34.6 Gradient accumulation: simulating large effective batch sizes ($B_{effective} = B_{physical} \\times \\text{accum\\_steps}$) under constrained VRAM"]}'::jsonb, '["Explain how this implementation prevents: Saving only model weights in checkpoints, failing to restore optimizer momentum and learning rate schedule upon resume.", "How does PyTorch Deep Dive VI: Training Loop Engineering, Checkpointing & Reproducibility scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-35', 'phase-09-lesson-35-sequence-modeling-from-recurrent-neural-n', 'module-4', 35, 'Lesson 4.35: Sequence Modeling: From Recurrent Neural Networks (RNNs) to Attention', 'Prerequisites: Phase 3, Lesson 9.13', 'Prerequisites: Phase 3, Lesson 9.13 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1750.0, '# Lesson 9.35: Sequence Modeling: From Recurrent Neural Networks (RNNs) to Attention

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 3, Lesson 9.13
- **Subtopics**:
  - `9.35.1` Sequence-to-sequence learning problem: modeling variable-length temporal sequences ($x_1, x_2, \dots, x_T$)
  - `9.35.2` Vanilla Recurrent Neural Networks (RNNs): hidden state recurrence ($h_t = \tanh(W_{hh} h_{t-1} + W_{xh} x_t + b)$)
  - `9.35.3` Backpropagation Through Time (BPTT): unrolling recurrence through time; mathematical proof of vanishing and exploding gradients in deep unrolls
  - `9.35.4` Gated architectures: Long Short-Term Memory (LSTM) cells (forget, input, output gates, cell state) and Gated Recurrent Units (GRU)
  - `9.35.5` The fundamental bottleneck of recurrent architectures: sequential $O(T)$ execution preventing hardware parallelism on GPUs
  - `9.35.6` The Attention breakthrough (Bahdanau, Vaswani): routing information directly between any two sequence positions in $O(1)$ path length
- **Key Failure Modes & Edge Cases**: Attempting to train standard vanilla RNNs on sequences longer than 50 tokens, causing vanishing gradients to stall training completely.
- **Verification & Mastery Check**: Implement an unrolled Vanilla RNN and LSTM forward pass in NumPy; demonstrate gradient vanishing over 30 time steps.
- **Project Application**: TransformerLab: Historical perspective and architectural comparison.', '{"solution.py": "# Phase 9 // Lesson 9.35: Sequence Modeling: From Recurrent Neural Networks (RNNs) to Attention\n\ndef solve():\n    \"\"\"\n    Verification: Implement an unrolled Vanilla RNN and LSTM forward pass in NumPy; demonstrate gradient vanishing ove\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.35", "subtopics_count": 6, "verification_criteria": "Implement an unrolled Vanilla RNN and LSTM forward pass in NumPy; demonstrate gradient vanishing over 30 time steps.", "subtopics": ["9.35.1 Sequence-to-sequence learning problem: modeling variable-length temporal sequences ($x_1, x_2, \\dots, x_T$)", "9.35.2 Vanilla Recurrent Neural Networks (RNNs): hidden state recurrence ($h_t = \\tanh(W_{hh} h_{t-1} + W_{xh} x_t + b)$)", "9.35.3 Backpropagation Through Time (BPTT): unrolling recurrence through time; mathematical proof of vanishing and exploding gradients in deep unrolls", "9.35.4 Gated architectures: Long Short-Term Memory (LSTM) cells (forget, input, output gates, cell state) and Gated Recurrent Units (GRU)", "9.35.5 The fundamental bottleneck of recurrent architectures: sequential $O(T)$ execution preventing hardware parallelism on GPUs", "9.35.6 The Attention breakthrough (Bahdanau, Vaswani): routing information directly between any two sequence positions in $O(1)$ path length"]}'::jsonb, '["Explain how this implementation prevents: Attempting to train standard vanilla RNNs on sequences longer than 50 tokens, causing vanishing gradients to stall train", "How does Sequence Modeling: From Recurrent Neural Networks (RNNs) to Attention scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
